INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-01-975', 'DIK-01', 'TORQUE_DRAG', 3024.29, 3062.48, 3024.29, 'Surma Group', '2020-07-25 00:00:00', 10.9, 7.9, 'MEDIUM', 0, 1.25, 'Severe torque fluctuations (> 28 kN.m) due to hole cleaning deficit and dogleg severity in Girujan clays', 'Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 'Torque stabilized back to 16 kN.m. Resumed drilling.', 'WCR_DIK-01_FINAL.pdf', 19, 'At depth 3024.29m in Surma Group, severe torque fluctuations (> 28 kn.m) due to hole cleaning deficit and dogleg severity in girujan clays. Action taken: Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 0.92, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-01-799', 'DIK-01', 'KICK', 3452.29, 3487.4, 3452.29, 'Barail Coal-Shale', '2020-05-26 00:00:00', 26.2, 23.2, 'CRITICAL', 0, 1.38, 'Encountered high-pressure gas sand stringer in Upper Barail; sudden D-exponent drop and pit gain of 2.4 m3', 'Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 'Well killed safely after 16 hours. Resumed drilling with zero gas units.', 'WCR_DIK-01_FINAL.pdf', 32, 'At depth 3452.29m in Barail Coal-Shale, encountered high-pressure gas sand stringer in upper barail; sudden d-exponent drop and pit gain of 2.4 m3. Action taken: Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 0.94, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-02-996', 'DIK-02', 'KICK', 3466.79, 3495.4, 3289.96, 'Barail Coal-Shale', '2021-06-23 00:00:00', 30.3, 27.3, 'CRITICAL', 0, 1.38, 'Encountered high-pressure gas sand stringer in Upper Barail; sudden D-exponent drop and pit gain of 2.4 m3', 'Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 'Well killed safely after 16 hours. Resumed drilling with zero gas units.', 'WCR_DIK-02_FINAL.pdf', 35, 'At depth 3466.79m in Barail Coal-Shale, encountered high-pressure gas sand stringer in upper barail; sudden d-exponent drop and pit gain of 2.4 m3. Action taken: Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 0.98, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-04-268', 'DIK-04', 'LOSS', 2207.63, 2229.04, 2207.63, 'Tipam Sandstone', '2020-01-05 00:00:00', 16.1, 13.1, 'CRITICAL', 47, 1.32, 'Natural micro-fractures in Tipam sands intersected under high ECD (> 1.34 sg)', 'Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 'Full circulation regained after 7.5 hours NPT. Drilling resumed with controlled ECD.', 'WCR_DIK-04_FINAL.pdf', 24, 'At depth 2207.63m in Tipam Sandstone, natural micro-fractures in tipam sands intersected under high ecd (> 1.34 sg). Action taken: Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 0.98, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-07-546', 'DIK-07', 'KICK', 3646.27, 3666.97, 3646.27, 'Barail Coal-Shale', '2022-11-30 00:00:00', 15.7, 12.7, 'CRITICAL', 0, 1.38, 'Encountered high-pressure gas sand stringer in Upper Barail; sudden D-exponent drop and pit gain of 2.4 m3', 'Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 'Well killed safely after 16 hours. Resumed drilling with zero gas units.', 'WCR_DIK-07_FINAL.pdf', 12, 'At depth 3646.27m in Barail Coal-Shale, encountered high-pressure gas sand stringer in upper barail; sudden d-exponent drop and pit gain of 2.4 m3. Action taken: Shut-in on annular BOP. Recorded SIDPP=380 psi, SICP=520 psi. Circulated gas bubble via Wait & Weight method. Weighted up mud to 1.44 sg.', 0.97, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-07-968', 'DIK-07', 'STUCK', 4008.32, 4033.23, 4008.32, 'Kopili Shale', '2024-01-14 00:00:00', 15.4, 12.4, 'HIGH', 0, 1.3, 'Reactive Kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs', 'Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 'String freed after 11 hours. Conditioned mud with KCl-Polymer inhibitor.', 'WCR_DIK-07_FINAL.pdf', 15, 'At depth 4008.32m in Kopili Shale, reactive kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs. Action taken: Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 0.97, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-08-804', 'DIK-08', 'LOSS', 2377.74, 2407.57, 2281.48, 'Tipam Sandstone', '2020-08-06 00:00:00', 9.3, 6.3, 'WARNING', 37, 1.32, 'Natural micro-fractures in Tipam sands intersected under high ECD (> 1.34 sg)', 'Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 'Full circulation regained after 7.5 hours NPT. Drilling resumed with controlled ECD.', 'WCR_DIK-08_FINAL.pdf', 12, 'At depth 2377.74m in Tipam Sandstone, natural micro-fractures in tipam sands intersected under high ecd (> 1.34 sg). Action taken: Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 0.96, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-10-938', 'DIK-10', 'STUCK', 3946.03, 3983.47, 3946.03, 'Kopili Shale', '2021-09-29 00:00:00', 12.6, 9.6, 'HIGH', 0, 1.3, 'Reactive Kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs', 'Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 'String freed after 11 hours. Conditioned mud with KCl-Polymer inhibitor.', 'WCR_DIK-10_FINAL.pdf', 17, 'At depth 3946.03m in Kopili Shale, reactive kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs. Action taken: Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 0.9, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-DIK-16-495', 'DIK-16', 'TORQUE_DRAG', 1565.26, 1601.42, 1439.29, 'Girujan Clay', '2023-08-28 00:00:00', 10.1, 7.1, 'MEDIUM', 0, 1.25, 'Severe torque fluctuations (> 28 kN.m) due to hole cleaning deficit and dogleg severity in Girujan clays', 'Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 'Torque stabilized back to 16 kN.m. Resumed drilling.', 'WCR_DIK-16_FINAL.pdf', 33, 'At depth 1565.26m in Girujan Clay, severe torque fluctuations (> 28 kn.m) due to hole cleaning deficit and dogleg severity in girujan clays. Action taken: Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 0.98, true);
