INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-NHK-17-178', 'NHK-17', 'TORQUE_DRAG', 1343.01, 1370.64, 1343.01, 'Girujan Clay', '2021-05-30 00:00:00', 8.4, 5.4, 'MEDIUM', 0, 1.25, 'Severe torque fluctuations (> 28 kN.m) due to hole cleaning deficit and dogleg severity in Girujan clays', 'Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 'Torque stabilized back to 16 kN.m. Resumed drilling.', 'WCR_NHK-17_FINAL.pdf', 23, 'At depth 1343.01m in Girujan Clay, severe torque fluctuations (> 28 kn.m) due to hole cleaning deficit and dogleg severity in girujan clays. Action taken: Pumped high-viscosity tandem sweep. Back-reamed 12 stands with maximum flow rate.', 0.97, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-NHK-17-735', 'NHK-17', 'LOSS', 1928.24, 1952.38, 1928.24, 'Tipam Sandstone', '2021-11-05 00:00:00', 11.0, 8.0, 'CRITICAL', 47, 1.32, 'Natural micro-fractures in Tipam sands intersected under high ECD (> 1.34 sg)', 'Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 'Full circulation regained after 7.5 hours NPT. Drilling resumed with controlled ECD.', 'WCR_NHK-17_FINAL.pdf', 24, 'At depth 1928.24m in Tipam Sandstone, natural micro-fractures in tipam sands intersected under high ecd (> 1.34 sg). Action taken: Spotted 30 ppb coarse LCM pill (NutPlug + Mica). Reduced pump rate from 2400 to 2050 LPM. Reduced mud weight to 1.28 sg.', 0.93, true);
INSERT INTO events (event_id, well_id, type, md_from, md_to, tvd, formation, start_ts, duration_h, npt_h, severity, volume_lost_m3, mud_wt, cause, mitigation, outcome, source_doc_id, page, evidence_quote, confidence, verified) VALUES ('EV-NHK-17-398', 'NHK-17', 'STUCK', 3961.61, 4005.55, 3961.61, 'Kopili Shale', '2023-11-24 00:00:00', 24.6, 21.6, 'HIGH', 0, 1.3, 'Reactive Kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs', 'Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 'String freed after 11 hours. Conditioned mud with KCl-Polymer inhibitor.', 'WCR_NHK-17_FINAL.pdf', 35, 'At depth 3961.61m in Kopili Shale, reactive kopili shale sloughing and pack-off during wiper trip; overpull exceeded 140 klbs. Action taken: Jarred downwards at 110 klbs overpull. Spotted 50 bbl glycol-based lubricant pill. Worked pipe with 35 RPM rotation.', 0.95, true);
